package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/** The store of the sheet's plans and of the dates each has made its claim for. */
@Repository
public class Plans {

    private final JdbcTemplate jdbc;

    public Plans(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's plans, in the order they were added. */
    public List<Plan> list(String sheetId) {
        return jdbc.query("SELECT id, sheet_id, person_id, amount, start_date, every_days, end_date, day_of_month FROM plan "
                + "WHERE sheet_id = ? ORDER BY id",
                (rs, n) -> new Plan(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
                        rs.getBigDecimal("amount").setScale(2), rs.getDate("start_date").toLocalDate(),
                        rs.getInt("every_days"), rs.getDate("end_date").toLocalDate(), rs.getInt("day_of_month")),
                sheetId);
    }

    /** Adds the plan: the stored plan with its id. */
    public Plan add(Plan plan) {
        KeyHolder key = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO plan (sheet_id, person_id, amount, start_date, every_days, end_date, day_of_month) "
                    + "VALUES (?, ?, ?, ?, ?, ?, ?)", new String[] { "id" });
            ps.setString(1, plan.sheetId());
            ps.setLong(2, plan.personId());
            ps.setBigDecimal(3, plan.amount());
            ps.setDate(4, Date.valueOf(plan.start()));
            ps.setInt(5, plan.every());
            ps.setDate(6, Date.valueOf(plan.end()));
            ps.setInt(7, plan.day());
            return ps;
        }, key);
        return new Plan(key.getKey().longValue(), plan.sheetId(), plan.personId(), plan.amount(), plan.start(),
                plan.every(), plan.end(), plan.day());
    }

    /** The dates the plan has made its claim for. */
    public List<LocalDate> made(long planId) {
        return jdbc.query("SELECT on_date FROM plan_claim WHERE plan_id = ? ORDER BY on_date",
                (rs, n) -> rs.getDate("on_date").toLocalDate(), planId);
    }

    /** How many claims each plan of the sheet has made, by plan id (absent for none). */
    public Map<Long, Integer> madeCounts(String sheetId) {
        return jdbc.query("SELECT pc.plan_id, COUNT(*) AS n FROM plan_claim pc JOIN plan p ON p.id = pc.plan_id "
                + "WHERE p.sheet_id = ? GROUP BY pc.plan_id",
                (rs, n) -> Map.entry(rs.getLong("plan_id"), rs.getInt("n")), sheetId)
                .stream().collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
    }

    /** The plan's pauses, in the order they were made. */
    public List<PlanPause> pauses(long planId) {
        return jdbc.query("SELECT paused_on, resumed_on FROM plan_pause WHERE plan_id = ? ORDER BY id",
                (rs, n) -> new PlanPause(rs.getDate("paused_on").toLocalDate(),
                        rs.getDate("resumed_on") == null ? null : rs.getDate("resumed_on").toLocalDate()), planId);
    }

    /** Whether the plan is paused now: it has a pause not yet resumed. */
    public boolean paused(long planId) {
        return pauses(planId).stream().anyMatch(p -> p.resumedOn() == null);
    }

    /** Pauses the plan from the date. */
    public void pause(long planId, LocalDate date) {
        jdbc.update("INSERT INTO plan_pause (plan_id, paused_on) VALUES (?, ?)", planId, Date.valueOf(date));
    }

    /** Resumes the plan's open pause on the date. */
    public void resume(long planId, LocalDate date) {
        jdbc.update("UPDATE plan_pause SET resumed_on = ? WHERE plan_id = ? AND resumed_on IS NULL", Date.valueOf(date), planId);
    }

    /** The plan's amount changes, oldest first. */
    public List<PlanChange> changes(long planId) {
        return jdbc.query("SELECT changed_on, amount FROM plan_change WHERE plan_id = ? ORDER BY id",
                (rs, n) -> new PlanChange(rs.getDate("changed_on").toLocalDate(), rs.getBigDecimal("amount").setScale(2)), planId);
    }

    /** Changes the plan's amount on the date, keeping the change: the plan with its new amount. */
    public Plan changeAmount(Plan plan, BigDecimal amount, LocalDate date) {
        BigDecimal scaled = amount.setScale(2);
        jdbc.update("UPDATE plan SET amount = ? WHERE id = ?", scaled, plan.id());
        jdbc.update("INSERT INTO plan_change (plan_id, changed_on, amount) VALUES (?, ?, ?)", plan.id(), Date.valueOf(date), scaled);
        return new Plan(plan.id(), plan.sheetId(), plan.personId(), scaled, plan.start(), plan.every(), plan.end(), plan.day());
    }

    /** Records that the plan made the claim for the date. */
    public void markMade(long planId, LocalDate date, long claimId) {
        jdbc.update("INSERT INTO plan_claim (plan_id, on_date, claim_id) VALUES (?, ?, ?)", planId, Date.valueOf(date), claimId);
    }
}
