package net.officefloor.hq.app.plan;

import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPlan {
    public void respond(@Val Plan plan, Plans plans, Sheets sheets, ObjectResponse<PlanResponse> response) {
        response.send(PlanResponse.from(plan, plans.made(plan.id()).size(), sheets.today(plan.sheetId()), plans.pauses(plan.id()), plans.changes(plan.id())));
    }
}
-- A plan's amount changes: the day it was changed (the sheet's today) and the new amount. The plan's own amount is the
-- latest one, used for the claims generated from then on; claims already generated keep theirs.
CREATE TABLE plan_change (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    plan_id    BIGINT         NOT NULL REFERENCES plan (id),
    changed_on DATE           NOT NULL,
    amount     DECIMAL(19, 2) NOT NULL
);
CREATE INDEX plan_change_plan ON plan_change (plan_id);
-- A person's plans: an amount, a start date, every N days (at least 1) and an end date. Generating makes a DRAFT claim
-- for each plan date (the start, then every N days) up to the end and the sheet's today; plan_claim keeps each date a
-- plan has made its claim for, so a date is made once only, and a date the claim form refused is tried again next time.
CREATE TABLE plan (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(255)   NOT NULL,
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(19, 2) NOT NULL,
    start_date DATE           NOT NULL,
    every_days INT            NOT NULL,
    end_date   DATE           NOT NULL
);
CREATE INDEX plan_sheet ON plan (sheet_id);
CREATE TABLE plan_claim (
    plan_id  BIGINT NOT NULL REFERENCES plan (id),
    on_date  DATE   NOT NULL,
    claim_id BIGINT NOT NULL,
    PRIMARY KEY (plan_id, on_date)
);
